237	      .catch((e) => setErro(e.message))
238	      .finally(() => setLoading(false));
239	  }, []);
240	
241	  useEffect(() => { carregar(); }, [carregar]);
242	
243	  const handleRemover = async (cat) => {
244	    if (!window.confirm(`Remover "${cat.name}"? Produtos vinculados perderão a categoria.`)) return;
245	    setRemovendo(cat.id);
246	    try {
247	      await removerCategoriaGlobal(cat.id);
248	      setCategorias((prev) => prev.filter((c) => c.id !== cat.id));
249	    } catch (e) {
250	      alert(e.message);
251	    } finally {
252	      setRemovendo(null);
253	    }
254	  };
255	
256	  return (
