272	          >
273	            <Icon name="Plus" size={16} /> Nova Categoria
274	          </button>
275	        </div>
276	
277	        {erro && <p className="text-red-600 text-sm mb-4 bg-red-50 rounded-lg px-4 py-3">{erro}</p>}
278	
279	        {loading ? (
280	          <div className="flex justify-center py-16">
281	            <div className="w-8 h-8 border-4 border-blue-600 border-t-transparent rounded-full animate-spin" />
282	          </div>
283	        ) : categorias.length === 0 ? (
284	          <div className="bg-white rounded-2xl border p-14 text-center">
285	            <Icon name="Tag" size={44} className="text-gray-200 mx-auto mb-3" />
286	            <p className="text-gray-400 mb-4">Nenhuma categoria cadastrada</p>
287	            <button onClick={() => setModal('nova')}
288	              className="px-5 py-2.5 bg-blue-600 text-white text-sm font-semibold rounded-xl hover:bg-blue-700">
289	              Criar primeira categoria
290	            </button>
291	          </div>
292	        ) : (
293	          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
294	            <AnimatePresence>
295	              {categorias.map((cat) => (
296	                <motion.div
297	                  key={cat.id}
298	                  initial={{ opacity: 0, scale: 0.95 }}
299	                  animate={{ opacity: 1, scale: 1 }}
300	                  exit={{ opacity: 0, scale: 0.9 }}
301	                  className="bg-white rounded-2xl border border-gray-100 p-5 flex items-center gap-4 group hover:shadow-md transition-shadow"
302	                >
303	                  <div
304	                    className="w-14 h-14 rounded-2xl flex items-center justify-center text-white shadow-md flex-shrink-0"
305	                    style={{ background: `linear-gradient(135deg, ${cat.color_primary}, ${cat.color_secondary})` }}
306	                  >
307	                    <Icon name={cat.icon_name ?? 'Tag'} size={24} />
308	                  </div>
309	                  <div className="flex-1 min-w-0">
310	                    <p className="font-bold text-gray-900">{cat.name}</p>
311	                    <p className="text-xs text-gray-400 mt-0.5">
312	                      {cat.icon_name} · {cat.total_produtos ?? 0} produto(s)
313	                    </p>
314	                  </div>
315	                  <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
316	                    <button
317	                      onClick={() => setModal(cat)}
318	                      className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
319	                      title="Editar"
320	                    >
321	                      <Icon name="Pencil" size={15} />
