                    form.color_primary === par.c1 ? 'ring-2 ring-offset-2 ring-blue-500 scale-110' : 'hover:scale-105'
                  }`}
                  style={{ background: `linear-gradient(135deg, ${par.c1}, ${par.c2})` }}
                />
