                    onChange={(e) => set('color_primary', e.target.value)}
                    className="w-8 h-8 rounded cursor-pointer border-0" />
                  <input type="text" value={form.color_primary}
                    onChange={(e) => set('color_primary', e.target.value)}
                    className="flex-1 border rounded-lg px-2 py-1.5 text-xs font-mono" />
